package stringutils

// BUG 1: mirror index is len(s)-1-i-1 (off by one) instead of len(s)-1-i
func IsPalindrome(s string) bool {
	for i := 0; i < len(s)/2; i++ {
		if s[i] != s[len(s)-2-i] {
			return false
		}
	}
	return true
}

// BUG 2: swap assigns runes[i],runes[j] = runes[i],runes[j] (no-op)
func ReverseString(s string) string {
	runes := []rune(s)
	n := len(runes)
	for i := 0; i < n/2; i++ {
		j := n - 1 - i
		runes[i], runes[j] = runes[i], runes[j]
	}
	return string(runes)
}

// BUG 3: increments count by 2 instead of 1
func CountVowels(s string) int {
	count := 0
	for _, c := range s {
		switch c {
		case 'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U':
			count += 2
		}
	}
	return count
}

