package stringutils

import "testing"

func TestIsPalindromeTrue(t *testing.T) {
	if !IsPalindrome("abba") {
		t.Errorf("IsPalindrome(abba) = false, want true")
	}
}

func TestIsPalindromeFalse(t *testing.T) {
	if IsPalindrome("hello") {
		t.Errorf("IsPalindrome(hello) = true, want false")
	}
}

func TestReverseString(t *testing.T) {
	if got := ReverseString("abcde"); got != "edcba" {
		t.Errorf("ReverseString(abcde) = %q, want \"edcba\"", got)
	}
}

func TestCountVowels(t *testing.T) {
	if got := CountVowels("hello"); got != 2 {
		t.Errorf("CountVowels(hello) = %d, want 2", got)
	}
}
